        c.clear();
        c.set(y,mo,d,h,mi,s);
        c.set(Calendar.MILLISECOND, ms);
        return c;
    }
    static void show(String label, Calendar c){
        System.out.println(label+": "+c.get(Calendar.YEAR)+"-"+(c.get(Calendar.MONTH)+1)+"-"+c.get(Calendar.DAY_OF_MONTH)+" "+c.get(Calendar.HOUR_OF_DAY)+":"+c.get(Calendar.MINUTE)+":"+c.get(Calendar.SECOND)+"."+c.get(Calendar.MILLISECOND));
    }
    public static void main(String[] args) throws Exception {
        System.out.println("TZ="+java.util.TimeZone.getDefault());
        // SEMI_MONTH ceiling test
        Calendar c5 = cal(2008,0,5,10,0,0,0);
        show("ceil SEMI_MONTH day5 input", c5);
        show("ceil SEMI_MONTH day5 result", DateUtils.ceiling(c5, DateUtils.SEMI_MONTH));

