        Calendar first=null, last=null; int count=0;
        while(it.hasNext()){ Calendar x=it.next(); if(first==null) first=x; last=x; count++; }
        show("RANGE_MONTH_SUNDAY first", first);
        show("RANGE_MONTH_SUNDAY last", last);
        System.out.println("count="+count);

        // RANGE_WEEK_CENTER
        Calendar focus2 = cal(2002,6,4,10,0,0,0); // Thursday
        Iterator<Calendar> it2 = DateUtils.iterator(focus2, DateUtils.RANGE_WEEK_CENTER);
        Calendar f2=null,l2=null; int c2=0;
        while(it2.hasNext()){ Calendar x=it2.next(); if(f2==null) f2=x; l2=x; c2++; }
        show("RANGE_WEEK_CENTER first", f2);
        show("RANGE_WEEK_CENTER last", l2);
        System.out.println("count2="+c2);

        // RANGE_WEEK_RELATIVE
        Iterator<Calendar> it3 = DateUtils.iterator(cal(2002,6,4,10,0,0,0), DateUtils.RANGE_WEEK_RELATIVE);
        Calendar f3=null,l3=null; int c3=0;
        while(it3.hasNext()){ Calendar x=it3.next(); if(f3==null) f3=x; l3=x; c3++; }
        show("RANGE_WEEK_RELATIVE first", f3);
        show("RANGE_WEEK_RELATIVE last", l3);
        System.out.println("count3="+c3);

        // parseDate lenient overflow
        Date d = DateUtils.parseDate("20080132", "yyyyMMdd");
        show("parseDate lenient 20080132", DateUtils.toCalendar(d));
        try {
            DateUtils.parseDateStrictly("20080132", "yyyyMMdd");
            System.out.println("strictly did NOT throw (unexpected)");
        } catch (Exception e) {
            System.out.println("parseDateStrictly threw: "+e);
        }
    }
}
