import org.apache.commons.lang3.time.DateUtils;
import java.util.Calendar;
import java.util.Iterator;
import java.util.Date;

public class Probe {
    static Calendar cal(int y, int mo, int d, int h, int mi, int s, int ms) {
        Calendar c = Calendar.getInstance();
        c.clear();
        c.set(y, mo, d, h, mi, s);
        c.set(Calendar.MILLISECOND, ms);
        return c;
    }
    static void show(String label, Calendar c) {
        System.out.println(label + ": " + c.get(Calendar.YEAR) + "-" + (c.get(Calendar.MONTH) + 1) + "-" + c.get(Calendar.DAY_OF_MONTH)
                + " " + c.get(Calendar.HOUR_OF_DAY) + ":" + c.get(Calendar.MINUTE) + ":" + c.get(Calendar.SECOND) + "." + c.get(Calendar.MILLISECOND));
    }
    public static void main(String[] args) throws Exception {
        System.out.println("TZ=" + java.util.TimeZone.getDefault());
        Calendar c5 = cal(2008, 0, 5, 10, 0, 0, 0);
        show("ceil SEMI_MONTH day5 input", c5);
        show("ceil SEMI_MONTH day5 result", DateUtils.ceiling(c5, DateUtils.SEMI_MONTH));

        Calendar c20 = cal(2008, 0, 20, 10, 0, 0, 0);
        show("ceil SEMI_MONTH day20 result", DateUtils.ceiling(c20, DateUtils.SEMI_MONTH));

        Calendar c9 = cal(2008, 0, 9, 0, 0, 0, 0);
        show("round SEMI_MONTH day9", DateUtils.round(c9, DateUtils.SEMI_MONTH));
        Calendar c8 = cal(2008, 0, 8, 0, 0, 0, 0);
        show("round SEMI_MONTH day8", DateUtils.round(c8, DateUtils.SEMI_MONTH));
        Calendar c24 = cal(2008, 0, 24, 0, 0, 0, 0);
        show("round SEMI_MONTH day24", DateUtils.round(c24, DateUtils.SEMI_MONTH));
        Calendar c23 = cal(2008, 0, 23, 0, 0, 0, 0);
        show("round SEMI_MONTH day23", DateUtils.round(c23, DateUtils.SEMI_MONTH));

        Calendar h0 = cal(2008, 0, 1, 0, 10, 0, 0);
        show("round AM_PM hour0:10", DateUtils.round(h0, Calendar.AM_PM));
        Calendar h5 = cal(2008, 0, 1, 5, 10, 0, 0);
        show("round AM_PM hour5:10", DateUtils.round(h5, Calendar.AM_PM));
        Calendar h6 = cal(2008, 0, 1, 6, 10, 0, 0);
        show("round AM_PM hour6:10", DateUtils.round(h6, Calendar.AM_PM));
        Calendar h13 = cal(2008, 0, 1, 13, 10, 0, 0);
        show("round AM_PM hour13:10", DateUtils.round(h13, Calendar.AM_PM));
        Calendar h18 = cal(2008, 0, 1, 18, 10, 0, 0);
        show("round AM_PM hour18:10", DateUtils.round(h18, Calendar.AM_PM));

        Calendar ch0 = cal(2008, 0, 1, 0, 10, 0, 0);
        show("ceil AM_PM hour0:10", DateUtils.ceiling(ch0, Calendar.AM_PM));
        Calendar ch13 = cal(2008, 0, 1, 13, 10, 0, 0);
        show("ceil AM_PM hour13:10", DateUtils.ceiling(ch13, Calendar.AM_PM));

        Calendar focus = cal(2002, 6, 4, 10, 0, 0, 0);
        Iterator<Calendar> it = DateUtils.iterator(focus, DateUtils.RANGE_MONTH_SUNDAY);
        Calendar first = null, last = null;
        int count = 0;
        while (it.hasNext()) {
            Calendar x = it.next();
            if (first == null) {
                first = x;
            }
            last = x;
            count++;
        }
        show("RANGE_MONTH_SUNDAY first", first);
        show("RANGE_MONTH_SUNDAY last", last);
        System.out.println("count=" + count);

        Iterator<Calendar> it2 = DateUtils.iterator(cal(2002, 6, 4, 10, 0, 0, 0), DateUtils.RANGE_WEEK_CENTER);
        Calendar f2 = null, l2 = null;
        int c2 = 0;
        while (it2.hasNext()) {
            Calendar x = it2.next();
            if (f2 == null) {
                f2 = x;
            }
            l2 = x;
            c2++;
        }
        show("RANGE_WEEK_CENTER first", f2);
        show("RANGE_WEEK_CENTER last", l2);
        System.out.println("count2=" + c2);

        Iterator<Calendar> it3 = DateUtils.iterator(cal(2002, 6, 4, 10, 0, 0, 0), DateUtils.RANGE_WEEK_RELATIVE);
        Calendar f3 = null, l3 = null;
        int c3 = 0;
        while (it3.hasNext()) {
            Calendar x = it3.next();
            if (f3 == null) {
                f3 = x;
            }
            l3 = x;
            c3++;
        }
        show("RANGE_WEEK_RELATIVE first", f3);
        show("RANGE_WEEK_RELATIVE last", l3);
        System.out.println("count3=" + c3);

        Date d = DateUtils.parseDate("20080132", "yyyyMMdd");
        show("parseDate lenient 20080132", DateUtils.toCalendar(d));
        try {
            DateUtils.parseDateStrictly("20080132", "yyyyMMdd");
            System.out.println("strictly did NOT throw (unexpected)");
        } catch (Exception e) {
            System.out.println("parseDateStrictly threw: " + e);
        }
    }
}
